#include <iiMultimodalAgent/agent/McpTools.h>
#include <QtCore/QUrl>

iiMultimodalAgent::mcp::StdioOptions transport;
transport.program = "/absolute/path/to/app-mcp-server";
transport.arguments = {"--stdio"};
transport.workingDirectory = workspace;
iiMultimodalAgent::mcp::ClientOptions clientOptions;
clientOptions.roots = {QJsonObject{{"uri", QUrl::fromLocalFile(workspace).toString()}}};
auto client = std::make_shared<iiMultimodalAgent::mcp::StdioClient>(transport, clientOptions);
auto registry = std::make_shared<iiMultimodalAgent::agent::ToolRegistry>();
for (auto tool : iiMultimodalAgent::agent::mcpTools(client, {"society", "com.iisacc.society"}))
    registry->add(std::move(tool));
// registry를 기존 agent::Engine에 전달한다.
